import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            K_str = next(iterator)
            K = int(K_str)
        except StopIteration:
            break

        K -= 1

        binary = bin(K)[2:]

        digits = []
        for char in binary:
            if char == '0':
                digits.append('0')
            else:
                digits.append('1')

        results.append("".join(digits))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
